<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import {entries} from '@/data/site'
import {api} from '@/api/client'
const route=useRoute(),kind=route.path.startsWith('/projects/')?'project':'post'
const entry=computed(()=>entries.find(e=>e.slug===route.params.slug&&e.category===kind))
const liked=ref(false),saved=ref(false),comment=ref(''),notice=ref('')
async function action(type:'likes'|'bookmarks'){try{await api.post('/api/articles/'+String(route.params.slug)+'/'+type);if(type==='likes')liked.value=!liked.value;else saved.value=!saved.value}catch{notice.value='互动服务尚未完成接入，请稍后再试。'}}
async function submit(){if(!comment.value.trim())return;try{await api.post('/api/comments',{article_slug:route.params.slug,content:comment.value});comment.value='';notice.value='评论已提交'}catch{notice.value='请先登录，或稍后重试。'}}
</script>
<template><article v-if="entry" class="page-wrap article"><RouterLink :to="kind==='project'?'/projects/':'/posts/'" class="back">← 返回{{kind==='project'?'项目':'随笔'}}</RouterLink><header><span class="eyebrow">{{kind==='project'?'PROJECT NOTES':'JOURNAL ENTRY'}} / {{entry.date}}</span><h1>{{entry.title}}</h1><p>{{entry.summary}}</p><div class="tags"><span v-for="t in entry.tags" :key="t">{{t}}</span></div></header><section class="placeholder"><h2>正文内容迁移中</h2><p>Vue 页面路由已建立。完整 Markdown 正文、图片、目录与原始发布日期将在内容迁移阶段从 Hugo Page Bundle 导入。</p></section><section class="interaction"><div class="buttons"><button :class="{on:liked}" @click="action('likes')">♡ 点赞</button><button :class="{on:saved}" @click="action('bookmarks')">☆ 收藏</button></div><h2>留下你的想法</h2><textarea v-model="comment" rows="4" placeholder="写下友善、具体的评论..."></textarea><div class="submit"><span>{{notice}}</span><button @click="submit">发布评论</button></div></section></article><div v-else class="page-wrap missing"><h1>暂未找到这篇内容</h1><RouterLink to="/posts/">返回随笔</RouterLink></div></template>
<style scoped>.article{max-width:850px;padding-top:65px}.back{color:#817d91;font-size:12px}header{padding:42px 0 30px;border-bottom:1px solid #eae7f2}.article h1{margin:16px 0;font-size:clamp(34px,5vw,52px);letter-spacing:-.06em}.article header p{color:#817d91;line-height:1.9}.tags{display:flex;gap:7px;margin-top:20px}.tags span{padding:5px 10px;background:#f0edff;border-radius:99px;color:#6e5cbd;font-size:10px}.placeholder{margin:35px 0;padding:32px;border-radius:18px;background:#f5f3fc}.placeholder p{color:#817d91;font-size:13px;line-height:1.9}.interaction{padding:28px 0;border-top:1px solid #eae7f2}.buttons{display:flex;gap:10px}.buttons button{padding:10px 15px;border:1px solid #e7e3f0;border-radius:99px;background:white;color:#716b82}.buttons button.on{color:#7d6bc7;background:#f0edff}.interaction h2{font-size:19px;margin-top:30px}.interaction textarea{width:100%;padding:14px;border:1px solid #e7e3f0;border-radius:13px;resize:vertical}.submit{display:flex;justify-content:space-between;align-items:center;margin-top:12px;color:#918ba2;font-size:11px}.submit button{padding:10px 18px;border:0;border-radius:99px;background:#8170cc;color:white}.missing{text-align:center;padding:100px}</style>
